const fs = require('fs');
const path = require('path');

const now = new Date();
const yesterdayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0);
const yesterdayEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);

return $input.all().filter((item) => {
  const filePath = item.json.fileName;
  if (!filePath) return false;
  try {
    const stat = fs.statSync(path.resolve(filePath));
    return stat.mtime >= yesterdayStart && stat.mtime < yesterdayEnd;
  } catch (error) {
    return false;
  }
});
